import fs from 'fs';
import { createWorkspace, teardownWorkspace } from '@tigrisdata/agent-kit';
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';

async function main() {
    let workspace;
    try {
        const trialIdRaw = fs.readFileSync('/logs/artifacts/trial_id', 'utf-8').trim();
        const trialId = trialIdRaw.toLowerCase().replace(/[^a-z0-9.-]/g, '-');
        const workspaceName = `harbor-scoped-${trialId}`;

        workspace = await createWorkspace(workspaceName, { credentials: { role: "Editor" } });

        if (!workspace.bucket) {
            throw new Error("Workspace bucket is missing");
        }
        if (!workspace.credentials || !workspace.credentials.accessKeyId || !workspace.credentials.secretAccessKey) {
            throw new Error("Workspace scoped credentials are missing");
        }

        const s3 = new S3Client({
            region: "REDACTED",
            endpoint: "REDACTED",
            credentials: {
                accessKeyId: workspace.credentials.accessKeyId,
                secretAccessKey: workspace.credentials.secretAccessKey
            }
        });

        await s3.send(new PutObjectCommand({
            Bucket: workspace.bucket,
            Key: "greeting.txt",
            Body: "hello scoped"
        }));

        console.log(`SCOPED_UPLOAD_OK ${workspace.bucket}`);
    } catch (err) {
        console.error(err);
        process.exit(1);
    } finally {
        if (workspace) {
            await teardownWorkspace(workspace);
        }
    }
}

main();

